<?php
require __DIR__.'/src/bootstrap.php';require_login();
if(time()-(int)($_SESSION['last_activity']??time())>1800){session_destroy();header('Location: login.php?expired=1');exit;}$_SESSION['last_activity']=time();
$showClosed=($_GET['show']??'')==='closed';$q=db()->prepare("SELECT c.*,i.name institution_name,u.display_name assignee_name FROM claims_cases c JOIN institutions i ON i.id=c.institution_id LEFT JOIN users u ON u.id=c.assigned_to WHERE c.institution_id=? AND (c.stage=".($showClosed?"'closed'":"'search_1' OR c.stage='search_2' OR c.stage='search_3' OR c.stage='search_4' OR c.stage='resolution'")."  ) ORDER BY COALESCE(c.next_action_at,c.opened_at),c.opened_at");$q->execute([tenant_id()]);$cases=$q->fetchAll();
$closed=db()->prepare("SELECT COUNT(*) FROM claims_cases WHERE institution_id=? AND stage='closed'");$closed->execute([tenant_id()]);$closedCount=(int)$closed->fetchColumn();
render_start('Active cases');
echo '<div class="page-title"><div><p class="eyebrow">'.h(user()['institution_name']).'</p><h1>Claims Returned queue</h1><p class="muted">'.($showClosed?$closedCount.' closed':count($cases).' active').' · '.$closedCount.' closed</p></div>'.(can_edit()?'<a class="button" href="case.php">＋ New case</a>':'').'</div><p class="queue-filter"><a class="button '.(!$showClosed?'':'secondary'). '" href="index.php">Active cases</a> <a class="button '.($showClosed?'':'secondary'). '" href="index.php?show=closed">Closed cases ('.$closedCount.')</a></p>';
echo '<section class="card table-wrap"><table><thead><tr><th>Case / Patron</th><th>Institution</th><th>Item</th><th>Case type</th><th>Partner institution</th><th>Partner status</th><th>Overall status</th><th>Next action</th><th>Assigned</th></tr></thead><tbody>';
foreach($cases as $c){$status=$c['stage']==='closed'?($c['resolution']==='complete'?'Complete':'Not found'):str_replace('_',' ',$c['stage']);$isPartner=$c['loan_type']!=='local';echo '<tr><td><a href="case.php?id='.(int)$c['id'].'"><strong>'.h($c['public_id']).'</strong></a><br>'.h($c['patron_name']).'<small>'.h($c['patron_primary_id']).'</small></td><td>'.h($c['institution_name']).'</td><td>'.h($c['item_title']).'<small>'.h($c['item_barcode']??'').'</small></td><td>'.h($c['loan_type']).'</td><td>'.h($isPartner?($c['partner_name']?:'Not specified'):'—').'</td><td>'.h($isPartner?str_replace('_',' ',$c['partner_status']):'—').'</td><td><span class="badge">'.h($status).'</span></td><td>'.h($c['next_action_at']?date('M j, Y',strtotime($c['next_action_at'])):'—').'</td><td>'.h($c['assignee_name']??'Unassigned').'</td></tr>';}
if(!$cases)echo '<tr><td colspan="9" class="empty">'.($showClosed?'No closed cases.':'No active cases. Create one when a claim is received.').'</td></tr>';echo '</tbody></table></section>';
render_end();
